        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Convert a scalar to scoring text, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
            if hasattr(missing, "item") and bool(missing.item()):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute ideal character-Trie reuse from lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Keep requested column groups contiguous without changing their values."""
        if not col_merge:
            return list(order)

        positions = {column: i for i, column in enumerate(order)}
        claimed = set()
        owners = {}

        for requested in col_merge:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=positions.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Return a complete integer permutation satisfying merge constraints."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: i for i, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every row using its row-specific column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Build frequency-ranked and repeated-pair global permutations."""
        rows = len(text)
        width = len(columns)
        statistics = []

        for column in range(width):
            counts = Counter(text[row][column] for row in range(rows))
            mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            statistics.append((mass, len(counts)))

        ranked = sorted(
            range(width),
            key=lambda column: (
                -statistics[column][0],
                statistics[column][1],
                column,
            ),
        )

        first = self._normalize(columns, ranked, col_merge)

        examined = ranked[:min(28, width)]
        pair_scores = []

        for left in examined:
            for right in examined:
                if left == right:
                    continue

                counts = Counter(
                    text[row][left] + text[row][right]
                    for row in range(rows)
                )
                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                if score:
                    pair_scores.append((-score, left, right))

        pair_scores.sort()
        used = set()
        paired = []

        for _, left, right in pair_scores:
            if left in used or right in used:
                continue
            paired.extend((left, right))
            used.update((left, right))

        paired.extend(column for column in ranked if column not in used)
        second = self._normalize(columns, paired, col_merge)

        return [first, second], ranked

    def _prototype_candidate(self, text, columns, col_merge, base_order):
        """Construct bounded row-specific layouts by matching sampled rows to prototypes."""
        rows = len(text)
        width = len(columns)
        fallback = self._normalize(columns, base_order, col_merge)
        result = [fallback[:] for _ in range(rows)]

        if rows < 2 or width < 2:
            return result

        sample_rows = list(range(min(rows, 256)))
        active = base_order[:min(width, 32)]

        def make_string(row, order):
            """Serialize one row through a proposed column order."""
            return "".join(text[row][column] for column in order)

        initial = [make_string(row, active) for row in sample_rows]
        anchors = [0]
        prototypes = [initial[0]]

        while len(anchors) < min(4, len(sample_rows)):
            best_position = -1
            best_distance = -1

            for position, value in enumerate(initial):
                if position in anchors:
                    continue

                nearest = max(
                    self._lcp(value, prototype)
                    for prototype in prototypes
                )
                distance = len(value) - nearest

                if distance > best_distance:
                    best_distance = distance
                    best_position = position

            if best_position < 0:
                break

            anchors.append(best_position)
            prototypes.append(initial[best_position])

        for position, row in enumerate(sample_rows):
            prototype = max(
                prototypes,
                key=lambda candidate: self._lcp(initial[position], candidate),
            )

            remaining = list(active)
            chosen = []
            cursor = 0

            while remaining:
                best_column = remaining[0]
                best_score = -1

                for column in remaining:
                    score = self._lcp(
                        text[row][column],
                        prototype[cursor:],
                    )
                    if score > best_score:
                        best_score = score
                        best_column = column

                chosen.append(best_column)
                cursor += len(text[row][best_column])
                remaining.remove(best_column)

            tail = [column for column in base_order if column not in chosen]
            result[row] = self._normalize(
                columns,
                chosen + tail,
                col_merge,
            )

        return result

    def _neighbor_refine(
        self,
        text,
        columns,
        col_merge,
        orders,
        serialized,
        base_order,
    ):
        """Refine sampled rows against actual sorted neighbors using suffix packing."""
        rows = len(text)
        width = len(columns)

        if rows < 3 or width < 2:
            return [order[:] for order in orders]

        sorted_rows = sorted(
            range(rows),
            key=lambda row: (serialized[row], row),
        )

        interior_count = min(128, rows - 2)
        if interior_count <= 0:
            return [order[:] for order in orders]

        if interior_count == 1:
            positions = [len(sorted_rows) // 2]
        else:
            positions = [
                1 + ((rows - 3) * i) // (interior_count - 1)
                for i in range(interior_count)
            ]

        refined = [order[:] for order in orders]
        active_limit = min(24, width)
        active = list(base_order[:active_limit])

        for position in positions:
            row = sorted_rows[position]
            predecessor = serialized[sorted_rows[position - 1]]
            successor = serialized[sorted_rows[position + 1]]

            if self._lcp(serialized[row], predecessor) >= self._lcp(
                serialized[row], successor
            ):
                target = predecessor
            else:
                target = successor

            remaining = active[:]
            chosen = []
            cursor = 0

            while remaining:
                best_column = remaining[0]
                best_score = -1

                for column in remaining:
                    score = self._lcp(
                        text[row][column],
                        target[cursor:],
                    )
                    if score > best_score:
                        best_score = score
                        best_column = column

                chosen.append(best_column)
                cursor += len(text[row][best_column])
                remaining.remove(best_column)

            tail = [column for column in base_order if column not in chosen]
            refined[row] = self._normalize(
                columns,
                chosen + tail,
                col_merge,
            )

        return refined

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate bounded global, prototype, and neighbor-refined layouts."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_candidates, base_order = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_candidates:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((
                self._reuse(serialized),
                orders,
                serialized,
            ))

        prototype_orders = self._prototype_candidate(
            text,
            columns,
            col_merge,
            base_order,
        )
        prototype_serialized = self._serialize(text, prototype_orders)
        candidates.append((
            self._reuse(prototype_serialized),
            prototype_orders,
            prototype_serialized,
        ))

        incumbent = max(candidates, key=lambda item: item[0])

        refined_orders = self._neighbor_refine(
            text,
            columns,
            col_merge,
            incumbent[1],
            incumbent[2],
            base_order,
        )
        refined_serialized = self._serialize(text, refined_orders)
        candidates.append((
            self._reuse(refined_serialized),
            refined_orders,
            refined_serialized,
        ))

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(rows),
            key=lambda row: (best_serialized[row], row),
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings
